parameters.jsCode:
// Validar decisión: comprueba la salida del AI Agent contra los valores permitidos
// y contra lo que devolvieron las herramientas buscar_procedimientos y consultar_mis_solicitudes.
// Los datos controlados (id_consulta, origen, legajo, fecha_hora) se toman del disparador, nunca del modelo.
const entrada = $('Recibir consulta').first().json;
const item = $input.first().json;

const DECISIONES = ['RESPONDER', 'SOLICITAR_ACLARACION', 'DERIVAR'];
const PROCEDIMIENTOS = ['PRO-RH-001', 'PRO-RH-002', 'PRO-AF-001', 'PRO-IT-001', 'PRO-LG-001'];
const PROC_ADICIONALES = ['Fuera de alcance', 'SIN_CLASIFICAR'];
const CATEGORIAS = ['Informativa', 'Estado de solicitud', 'Requiere decisión humana', 'Incidente de seguridad', 'Dato sensible', 'Fuera de alcance', 'SIN_CLASIFICAR'];
const AREAS = ['Recursos Humanos', 'Salud Ocupacional', 'Administración y Finanzas', 'Mesa de Ayuda IT', 'Seguridad Informática', 'Pañol y Logística'];
const URGENCIAS = ['Normal', 'Alta'];
const RE_SOLICITUD = /^(VAC|LIC|RG|TKT|HM)-\d{4}-\d{4}$/;
const RE_SOLICITUD_G = /\b(?:VAC|LIC|RG|TKT|HM)-\d{4}-\d{4}\b/g;
const RE_FUENTE = /^(PRO-(?:RH|AF|IT|LG)-\d{3})\s*§\s*(\d+)$/;
const RESPUESTA_ERROR = 'En este momento no puedo procesar tu consulta. Por favor, intentá de nuevo más tarde o comunicate con el área correspondiente.';

const controlados = {
  id_consulta: String(entrada.id_consulta ?? ''),
  origen: String(entrada.origen ?? ''),
  legajo: String(entrada.legajo ?? '').trim().toUpperCase(),
  fecha_hora: String(entrada.fecha_hora ?? ''),
};

const normalizaciones = [];

// 1) Uso real de la herramienta RAG (pasos intermedios del agente)
const pasos = Array.isArray(item.intermediateSteps) ? item.intermediateSteps : [];
const llamadas = pasos.filter(p => p && p.action && p.action.tool === 'buscar_procedimientos');

function recolectar(valor, acc, prof) {
  if (prof > 10 || valor === null || valor === undefined) return;
  if (typeof valor === 'string') {
    const t = valor.trim();
    if (t.startsWith('{') || t.startsWith('[')) {
      try { recolectar(JSON.parse(t), acc, prof + 1); } catch (e) { /* texto no JSON */ }
    }
    return;
  }
  if (Array.isArray(valor)) { valor.forEach(v => recolectar(v, acc, prof + 1)); return; }
  if (typeof valor === 'object') {
    const meta = (valor.metadata && valor.metadata.procedimiento) ? valor.metadata : (valor.procedimiento && valor.seccion_numero !== undefined ? valor : null);
    if (meta) {
      acc.push({ procedimiento: String(meta.procedimiento), seccion: String(meta.seccion_numero ?? ''), titulo: String(meta.seccion_titulo ?? '') });
      return;
    }
    Object.values(valor).forEach(v => recolectar(v, acc, prof + 1));
  }
}

const busquedas = llamadas.map(p => {
  const frags = [];
  recolectar(p.observation, frags, 0);
  const ti = p.action.toolInput;
  const consulta = typeof ti === 'string' ? ti : (ti && (ti.input || ti.query)) || JSON.stringify(ti);
  return { consulta: String(consulta).slice(0, 300), fragmentos: frags.map(f => f.procedimiento + ' §' + f.seccion + ' ' + f.titulo) };
});
const recuperadas = new Set();
busquedas.forEach(b => b.fragmentos.forEach(f => recuperadas.add(f.split(' ').slice(0, 2).join(' '))));
const rag = { usado: llamadas.length > 0, cantidad_busquedas: llamadas.length, busquedas, secciones_recuperadas: Array.from(recuperadas) };

// 1b) Uso de consultar_mis_solicitudes: solo solicitudes autorizadas por el control de acceso y solo campos mínimos
const llamadasSol = pasos.filter(p => p && p.action && p.action.tool === 'consultar_mis_solicitudes');
function recolectarFilas(valor, acc, prof) {
  if (prof > 10 || valor === null || valor === undefined) return;
  if (typeof valor === 'string') {
    const t = valor.trim();
    if (t.startsWith('{') || t.startsWith('[')) {
      try { recolectarFilas(JSON.parse(t), acc, prof + 1); } catch (e) { /* texto no JSON */ }
    }
    return;
  }
  if (Array.isArray(valor)) { valor.forEach(v => recolectarFilas(v, acc, prof + 1)); return; }
  if (typeof valor === 'object') {
    if (valor.id_solicitud !== undefined) { acc.push(valor); return; }
    Object.values(valor).forEach(v => recolectarFilas(v, acc, prof + 1));
  }
}
const filasSol = [];
llamadasSol.forEach(p => recolectarFilas(p.observation, filasSol, 0));
const idsPropios = Array.from(new Set(filasSol.map(f => String(f.id_solicitud).trim())));
let autorizadas = [];
try { autorizadas = ($('Control de acceso a solicitudes').first().json.solicitudes || []).map(x => String(x.id_solicitud).trim()); } catch (e) { autorizadas = []; }
const filasAjenas = filasSol.filter(f => !autorizadas.includes(String(f.id_solicitud).trim()));
const CAMPOS_SOLICITUD = ['id_solicitud', 'procedimiento', 'estado', 'fecha_estado', 'fecha_inicio', 'fecha_fin'];
const camposRecibidos = Array.from(new Set(filasSol.flatMap(f => Object.keys(f))));
const camposExtra = camposRecibidos.filter(c => !CAMPOS_SOLICITUD.includes(c));
const solicitudes = { usada: llamadasSol.length > 0, cantidad_llamadas: llamadasSol.length, ids_devueltos: idsPropios, campos_recibidos: camposRecibidos, filas_no_autorizadas: filasAjenas.length };

function salidaError(codigo, errores, detalle) {
  return [{ json: {
    ...controlados,
    decision: '', procedimiento: 'SIN_CLASIFICAR', categoria: 'SIN_CLASIFICAR', area_destino: '', urgencia: 'Normal',
    respuesta: RESPUESTA_ERROR, resumen: '[no disponible]', fuentes: '', id_solicitud: '',
    estado_procesamiento: 'ERROR', codigo_error: codigo,
    control: { errores, advertencias: [], normalizaciones, rag, solicitudes, detalle_tecnico: String(detalle || '').slice(0, 300) },
  } }];
}

// 2) Falla del agente (salida de error del nodo)
if (item.error) {
  const msg = String(typeof item.error === 'string' ? item.error : (item.error.message || JSON.stringify(item.error)));
  let codigo = 'ERR_LLM_NO_DISPONIBLE';
  if (/google sheets|spreadsheet|sheets/i.test(msg)) codigo = 'ERR_SHEETS';
  else if (/pars|format_final_json_response|output parser|structured|schema|JSON/i.test(msg)) codigo = 'ERR_LLM_SALIDA_INVALIDA';
  else if (/supabase|match_documents|vector|PGRST|postgres/i.test(msg)) codigo = 'ERR_VECTOR_STORE';
  else if (/timeout|timed out|ETIMEDOUT|deadline/i.test(msg)) codigo = 'ERR_LLM_TIMEOUT';
  return salidaError(codigo, ['Falla del AI Agent'], msg);
}

// 2b) La herramienta de solicitudes solo puede devolver solicitudes autorizadas y campos mínimos
if (filasAjenas.length > 0) return salidaError('ERR_SHEETS', ['consultar_mis_solicitudes devolvió solicitudes no autorizadas'], '');
if (camposExtra.length > 0) return salidaError('ERR_SHEETS', ['consultar_mis_solicitudes devolvió campos no previstos'], camposExtra.join(', '));

// 3) Salida estructurada
let o = item.output;
if (typeof o === 'string') { try { o = JSON.parse(o); } catch (e) { o = null; } }
if (!o || typeof o !== 'object') return salidaError('ERR_LLM_SALIDA_INVALIDA', ['La salida del agente no es un objeto JSON'], '');

const errores = [];
const advertencias = [];
const txt = v => (v === null || v === undefined) ? '' : String(v).trim();
const d = {
  decision: txt(o.decision), procedimiento: txt(o.procedimiento), categoria: txt(o.categoria),
  area_destino: txt(o.area_destino), urgencia: txt(o.urgencia), respuesta: txt(o.respuesta),
  resumen: txt(o.resumen), id_solicitud: txt(o.id_solicitud),
};
const fuentesLista = Array.isArray(o.fuentes) ? o.fuentes.map(txt).filter(Boolean) : (txt(o.fuentes) ? txt(o.fuentes).split(/[;,]/).map(txt).filter(Boolean) : []);

// Normalización determinística: sin procedimiento determinado, la categoría también queda sin clasificar
if (d.procedimiento === 'SIN_CLASIFICAR' && d.categoria !== 'SIN_CLASIFICAR') {
  normalizaciones.push('categoria: "' + d.categoria + '" -> "SIN_CLASIFICAR" porque procedimiento = SIN_CLASIFICAR');
  d.categoria = 'SIN_CLASIFICAR';
}

// Fuentes: se agregan las secciones citadas en la respuesta que fueron recuperadas y faltan en la lista
let procActual = PROCEDIMIENTOS.includes(d.procedimiento) ? d.procedimiento : '';
const reCita = /(PRO-(?:RH|AF|IT|LG)-\d{3})|secci(?:ón|ones)\s+(\d+(?:\s*(?:,|y|e)\s*\d+)*)/gi;
let mc;
while ((mc = reCita.exec(d.respuesta)) !== null) {
  if (mc[1]) { procActual = mc[1].toUpperCase(); continue; }
  if (!procActual) continue;
  (mc[2].match(/\d+/g) || []).forEach(n => {
    const clave = procActual + ' §' + n;
    const yaEsta = fuentesLista.some(f => { const m = f.match(RE_FUENTE); return m && (m[1] + ' §' + m[2]) === clave; });
    if (yaEsta) return;
    if (recuperadas.has(clave)) { fuentesLista.push(clave); normalizaciones.push('fuentes: se agregó ' + clave + ', citada en la respuesta y recuperada por la herramienta'); }
    else advertencias.push('la respuesta cita ' + clave + ', que no fue recuperada en esta consulta');
  });
}

// Solicitudes mencionadas en la respuesta: solo las propias o las que escribió el empleado
(d.respuesta.match(RE_SOLICITUD_G) || []).forEach(id => {
  if (!idsPropios.includes(id) && !String(entrada.mensaje || '').includes(id)) errores.push('la respuesta menciona una solicitud no respaldada: ' + id);
});

// Valores permitidos
if (!DECISIONES.includes(d.decision)) errores.push('decision no permitida: ' + d.decision);
if (!PROCEDIMIENTOS.includes(d.procedimiento) && !PROC_ADICIONALES.includes(d.procedimiento)) errores.push('procedimiento no permitido: ' + d.procedimiento);
if (!CATEGORIAS.includes(d.categoria)) errores.push('categoria no permitida: ' + d.categoria);
if (d.area_destino !== '' && !AREAS.includes(d.area_destino)) errores.push('area_destino no permitida: ' + d.area_destino);
if (!URGENCIAS.includes(d.urgencia)) errores.push('urgencia no permitida: ' + d.urgencia);
if (d.id_solicitud !== '' && !RE_SOLICITUD.test(d.id_solicitud)) errores.push('id_solicitud con formato inválido');
if (d.id_solicitud !== '' && !String(entrada.mensaje || '').includes(d.id_solicitud)) errores.push('id_solicitud no figura en el mensaje del empleado');
if (!d.respuesta) errores.push('respuesta vacía');
if (d.respuesta.length > 1200) errores.push('respuesta demasiado larga');
if (!d.resumen) errores.push('resumen vacío');
if (d.resumen.split(/\s+/).length > 25) advertencias.push('resumen de más de 20 palabras');

// Coherencia
if (d.decision === 'DERIVAR' && d.area_destino === '') errores.push('DERIVAR sin area_destino');
if (d.decision !== 'DERIVAR' && d.area_destino !== '') errores.push('area_destino informada sin DERIVAR');
if ((d.categoria === 'Requiere decisión humana' || d.categoria === 'Incidente de seguridad') && d.decision !== 'DERIVAR') errores.push('categoria ' + d.categoria + ' sin DERIVAR');
if (d.categoria === 'Incidente de seguridad' && (d.area_destino !== 'Seguridad Informática' || d.urgencia !== 'Alta')) errores.push('incidente de seguridad sin Seguridad Informática y urgencia Alta');
if ((d.procedimiento === 'Fuera de alcance') !== (d.categoria === 'Fuera de alcance')) errores.push('procedimiento y categoria Fuera de alcance no coinciden');
if (d.decision === 'RESPONDER' && PROCEDIMIENTOS.includes(d.procedimiento) && d.categoria !== 'Estado de solicitud' && fuentesLista.length === 0) errores.push('RESPONDER sobre un procedimiento sin fuentes');

// Fuentes: formato y respaldo en lo recuperado
fuentesLista.forEach(f => {
  const m = f.match(RE_FUENTE);
  if (!m) { errores.push('fuente con formato inválido: ' + f); return; }
  const clave = m[1] + ' §' + m[2];
  if (!recuperadas.has(clave)) errores.push('fuente no recuperada por la herramienta: ' + clave);
  if (PROCEDIMIENTOS.includes(d.procedimiento) && m[1] !== d.procedimiento) advertencias.push('fuente de otro procedimiento: ' + clave);
});
if (!rag.usado) {
  if (PROCEDIMIENTOS.includes(d.procedimiento) && d.categoria !== 'Estado de solicitud') errores.push('clasificó en un procedimiento sin usar buscar_procedimientos');
  else advertencias.push('no usó buscar_procedimientos');
}

// Lenguaje de aprobación o de trámite ejecutado (control heurístico)
if (/(te (lo |la )?(apruebo|autorizo)|qued(a|ó|an|aron) (aprobad|autorizad)[oa]s?|(ya )?(cargu[eé]|registr[eé]|envi[eé]|modifiqu[eé]|cancel[eé]) (la|tu|el|un|una)\b)/i.test(d.respuesta)) {
  advertencias.push('la respuesta contiene una expresión de aprobación o de trámite ejecutado; revisar');
}

// Afirmación de una derivación, registro, envío o aviso que el agente no ejecuta (control heurístico)
if (/(se deriv(a\b|ó)|derivamos|deriv[eé] (tu|la|el)\b|(fue|qued[oó]|ha sido) (derivad|registrad|notificad|enviad)[oa]|registramos|notifiqu[eé]|notificamos|se notific[oó]|enviamos|ya avis[eé])/i.test(d.respuesta)) {
  advertencias.push('la respuesta afirma una derivación, registro, envío o aviso no ejecutado; revisar');
}

if (errores.length > 0) return salidaError('ERR_LLM_SALIDA_INVALIDA', errores, JSON.stringify(o).slice(0, 300));

return [{ json: {
  ...controlados,
  decision: d.decision, procedimiento: d.procedimiento, categoria: d.categoria,
  area_destino: d.area_destino, urgencia: d.urgencia, respuesta: d.respuesta, resumen: d.resumen,
  fuentes: fuentesLista.join('; '), id_solicitud: d.id_solicitud,
  estado_procesamiento: 'COMPLETADO', codigo_error: '',
  control: { errores: [], advertencias, normalizaciones, rag, solicitudes },
} }];

// Validar empleado: comprueba, con lógica fija y sin IA, que el legajo recibido exista en Empleados,
// que la fila corresponda a ese legajo y que el empleado esté activo.
// Solo deja pasar al agente los campos mínimos necesarios.
const entrada = $('Recibir consulta').first().json;
const items = $input.all().map(i => i.json || {});
const legajo = String(entrada.legajo ?? '').trim().toUpperCase();
const base = {
  id_consulta: String(entrada.id_consulta ?? ''),
  origen: String(entrada.origen ?? ''),
  legajo,
  fecha_hora: String(entrada.fecha_hora ?? ''),
};
const RESPUESTA_LEGAJO = 'No pude validar tu legajo. Revisá que esté bien escrito, con el formato LEG-0000, y volvé a enviar tu consulta. Si el problema continúa, consultá a Recursos Humanos.';
const RESPUESTA_ERROR = 'En este momento no puedo procesar tu consulta. Por favor, intentá de nuevo más tarde o comunicate con el área correspondiente.';

function sinAgente(estado, codigo, resumen, respuesta, motivo) {
  return [{ json: { ...base, valido: false, motivo, salida: {
    ...base,
    decision: '', procedimiento: 'SIN_CLASIFICAR', categoria: 'SIN_CLASIFICAR', area_destino: '', urgencia: 'Normal',
    respuesta, resumen, fuentes: '', id_solicitud: '',
    estado_procesamiento: estado, codigo_error: codigo,
    control: { errores: [], advertencias: [], normalizaciones: [], motivo },
  } } }];
}

if (items.some(r => r.error)) return sinAgente('ERROR', 'ERR_SHEETS', '[no disponible]', RESPUESTA_ERROR, 'ERROR_LECTURA_EMPLEADOS');
if (!/^LEG-\d{4}$/.test(legajo)) return sinAgente('BLOQUEADO', '', 'Legajo con formato inválido', RESPUESTA_LEGAJO, 'LEGAJO_FORMATO_INVALIDO');

const filas = items.filter(r => String(r.legajo ?? '').trim() !== '');
const propias = filas.filter(r => String(r.legajo).trim().toUpperCase() === legajo);
if (filas.length === 0) return sinAgente('BLOQUEADO', '', 'Legajo inexistente', RESPUESTA_LEGAJO, 'LEGAJO_INEXISTENTE');
if (propias.length !== 1 || filas.length !== 1) return sinAgente('ERROR', 'ERR_SHEETS', '[no disponible]', RESPUESTA_ERROR, 'DATOS_DE_EMPLEADO_INCONSISTENTES');

const e = propias[0];
const activo = String(e.activo ?? '').trim().toUpperCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
if (activo !== 'SI') return sinAgente('BLOQUEADO', '', 'Legajo inactivo', RESPUESTA_LEGAJO, 'LEGAJO_INACTIVO');

return [{ json: {
  ...base,
  mensaje: String(entrada.mensaje ?? ''),
  valido: true,
  motivo: 'OK',
  empleado: {
    sede: String(e.sede ?? ''),
    fecha_ingreso: String(e.fecha_ingreso ?? ''),
    saldo_vacaciones: e.saldo_vacaciones ?? '',
  },
} }];

// Legajo inexistente o inactivo, solicitud que no es propia o error de lectura: se devuelve la salida fija
// preparada por "Validar empleado" o por "Control de acceso a solicitudes", sin invocar al agente.
return [{ json: $input.first().json.salida }];

// Control de acceso a solicitudes: regla fija, sin IA.
// Las filas se leyeron de Solicitudes filtrando por el legajo validado por el workflow.
// Si el mensaje menciona un número de solicitud que no pertenece a ese legajo, se responde
// con un texto fijo, sin invocar al agente y sin revelar si la solicitud existe.
const v = $('Validar empleado').first().json;
const items = $input.all().map(i => i.json || {});
const RE_ID = /\b(?:VAC|LIC|RG|TKT|HM)-\d{4}-\d{4}\b/gi;
const PROC = { VAC: 'PRO-RH-001', LIC: 'PRO-RH-002', RG: 'PRO-AF-001', TKT: 'PRO-IT-001', HM: 'PRO-LG-001' };
const RESPUESTA_ERROR = 'En este momento no puedo procesar tu consulta. Por favor, intentá de nuevo más tarde o comunicate con el área correspondiente.';
const base = { id_consulta: v.id_consulta, origen: v.origen, legajo: v.legajo, fecha_hora: v.fecha_hora };

function sinAgente(estado, codigo, procedimiento, categoria, resumen, respuesta, motivo, extra) {
  return [{ json: { ...base, valido: false, motivo, salida: {
    ...base,
    decision: '', procedimiento, categoria, area_destino: '', urgencia: 'Normal',
    respuesta, resumen, fuentes: '', id_solicitud: '',
    estado_procesamiento: estado, codigo_error: codigo,
    control: { errores: [], advertencias: [], normalizaciones: [], motivo, ...(extra || {}) },
  } } }];
}

if (items.some(r => r.error)) return sinAgente('ERROR', 'ERR_SHEETS', 'SIN_CLASIFICAR', 'SIN_CLASIFICAR', '[no disponible]', RESPUESTA_ERROR, 'ERROR_LECTURA_SOLICITUDES');

const filas = items.filter(r => String(r.id_solicitud ?? '').trim() !== '');
if (filas.some(r => String(r.legajo ?? '').trim().toUpperCase() !== v.legajo)) {
  return sinAgente('ERROR', 'ERR_SHEETS', 'SIN_CLASIFICAR', 'SIN_CLASIFICAR', '[no disponible]', RESPUESTA_ERROR, 'FILAS_DE_OTRO_LEGAJO');
}

const propias = new Set(filas.map(r => String(r.id_solicitud).trim().toUpperCase()));
const mencionadas = Array.from(new Set((String(v.mensaje || '').match(RE_ID) || []).map(x => x.toUpperCase())));
const noPropias = mencionadas.filter(id => !propias.has(id));

if (noPropias.length > 0) {
  const prefijos = Array.from(new Set(noPropias.map(id => id.split('-')[0])));
  const procedimiento = prefijos.length === 1 ? PROC[prefijos[0]] : 'SIN_CLASIFICAR';
  const categoria = procedimiento === 'SIN_CLASIFICAR' ? 'SIN_CLASIFICAR' : 'Estado de solicitud';
  const respuesta = (noPropias.length === 1
    ? 'La solicitud ' + noPropias[0] + ' no figura entre tus solicitudes registradas.'
    : 'Las solicitudes ' + noPropias.join(', ') + ' no figuran entre tus solicitudes registradas.')
    + ' Solo puedo informarte sobre las solicitudes registradas a tu nombre.';
  return sinAgente('BLOQUEADO', '', procedimiento, categoria, 'Consulta de una solicitud que no figura entre las propias', respuesta,
    'SOLICITUD_NO_PROPIA', { solicitudes_mencionadas: mencionadas.length, solicitudes_no_propias: noPropias.length });
}

// Campos mínimos que podrá ver el agente; el resto de las columnas no sale de este nodo.
const txt = x => (x === null || x === undefined) ? '' : String(x).trim();
const solicitudes = filas.map(r => ({
  id_solicitud: txt(r.id_solicitud), procedimiento: txt(r.procedimiento), estado: txt(r.estado),
  fecha_estado: txt(r.fecha_estado), fecha_inicio: txt(r.fecha_inicio), fecha_fin: txt(r.fecha_fin),
}));

return [{ json: { ...v, solicitudes_propias: filas.length, solicitudes_mencionadas: mencionadas.length, solicitudes } }];

// Devuelve solo los campos mínimos de las solicitudes del empleado validado.
// Los datos provienen de la lectura fija hecha por el workflow; la herramienta no recibe parámetros del modelo.
const datos = $('Control de acceso a solicitudes').first().json;
return JSON.stringify(Array.isArray(datos.solicitudes) ? datos.solicitudes : []);

// Preparar registro: arma, con lógica fija, la fila de Consultas y la respuesta final.
// Todos los identificadores y datos de control salen del workflow, no del modelo.
const r = $input.first().json;
const entrada = $('Recibir consulta').first().json;

const ESTADOS = ['COMPLETADO', 'BLOQUEADO', 'ERROR'];
const DECISIONES = ['RESPONDER', 'SOLICITAR_ACLARACION', 'DERIVAR'];
const PROCEDIMIENTOS = ['PRO-RH-001', 'PRO-RH-002', 'PRO-AF-001', 'PRO-IT-001', 'PRO-LG-001', 'Fuera de alcance', 'SIN_CLASIFICAR'];
const CATEGORIAS = ['Informativa', 'Estado de solicitud', 'Requiere decisión humana', 'Incidente de seguridad', 'Dato sensible', 'Fuera de alcance', 'SIN_CLASIFICAR'];
const CODIGOS = ['ERR_LLM_NO_DISPONIBLE', 'ERR_LLM_TIMEOUT', 'ERR_LLM_SALIDA_INVALIDA', 'ERR_VECTOR_STORE', 'ERR_SHEETS'];
const AREAS = ['Recursos Humanos', 'Salud Ocupacional', 'Administración y Finanzas', 'Mesa de Ayuda IT', 'Seguridad Informática', 'Pañol y Logística'];
const URGENCIAS = ['Normal', 'Alta'];
const txt = v => (v === null || v === undefined) ? '' : String(v).trim();
const de = (v, lista, defecto) => lista.includes(txt(v)) ? txt(v) : defecto;

// Resumen breve y sanitizado: nunca el mensaje original
function sanitizar(t) {
  let s = txt(t).replace(/[\r\n\t]+/g, ' ').replace(/\s{2,}/g, ' ');
  if (!s) return '[no disponible]';
  if (/(contrase[ñn]a|password|token|diagn[oó]stic|certificado|enfermedad|tratamiento|medicaci[oó]n|estudios? m[eé]dic|\bcbu\b|tarjeta de cr[eé]dito|\bdni\b)/i.test(s)) return '[contenido no registrado]';
  s = s.replace(/[\w.+-]+@[\w-]+(\.[\w-]+)+/g, '[correo]').replace(/\d{6,}/g, '[número]');
  s = s.replace(/^[=+\-@]+/, '').trim();
  if (s.length > 160) s = s.slice(0, 157).trimEnd() + '...';
  return s || '[no disponible]';
}

const id_consulta = txt(entrada.id_consulta);
const origen = txt(entrada.origen);
const legajoEntrada = txt(entrada.legajo).toUpperCase();
const datosControlValidos = /^CON-[A-Za-z0-9-]{1,60}$/.test(id_consulta) && ['CHAT', 'WEBHOOK'].includes(origen);

const estado = de(r.estado_procesamiento, ESTADOS, 'ERROR');
const sinDecision = estado !== 'COMPLETADO';
const decision = sinDecision ? '' : de(r.decision, DECISIONES, '');
const procedimiento = de(r.procedimiento, PROCEDIMIENTOS, 'SIN_CLASIFICAR');
const categoria = procedimiento === 'SIN_CLASIFICAR' ? 'SIN_CLASIFICAR' : de(r.categoria, CATEGORIAS, 'SIN_CLASIFICAR');
const area_destino = de(r.area_destino, AREAS, '');
const codigo_error = estado === 'ERROR' ? de(r.codigo_error, CODIGOS, 'ERR_LLM_SALIDA_INVALIDA') : '';

const fila = {
  id_consulta,
  fecha_hora: txt(entrada.fecha_hora).slice(0, 16),
  origen,
  legajo: /^LEG-\d{4}$/.test(legajoEntrada) ? legajoEntrada : '[no válido]',
  procedimiento,
  categoria,
  decision,
  estado_procesamiento: estado,
  codigo_error,
  area_destino,
  urgencia: de(r.urgencia, URGENCIAS, 'Normal'),
  resumen: sanitizar(r.resumen),
  fuentes: txt(r.fuentes).slice(0, 200),
  id_solicitud: /^(VAC|LIC|RG|TKT|HM)-\d{4}-\d{4}$/.test(txt(r.id_solicitud)) ? txt(r.id_solicitud) : '',
  // La derivación queda pendiente; la actualiza una persona. No implica aviso ni atención.
  estado_derivacion: area_destino ? 'Pendiente' : '',
};
// Estado del correo de aviso, independiente del estado de la derivación humana.
// PENDIENTE solo para derivaciones válidas; ENVIADO o ERROR los escribe el workflow después del envío.
fila.estado_aviso = (fila.decision === 'DERIVAR' && estado === 'COMPLETADO' && fila.estado_derivacion === 'Pendiente') ? 'PENDIENTE' : 'NO_APLICA';

const salida = { ...r, decision: fila.decision, estado_procesamiento: fila.estado_procesamiento, codigo_error: fila.codigo_error };
return [{ json: { puede_registrar: datosControlValidos, fila, salida } }];

// Decidir inserción: evita duplicados comprobando id_consulta en Consultas antes de escribir.
const prep = $('Preparar registro').first().json;
const items = $input.all().map(i => i.json || {});
const RESPUESTA_ERROR = 'En este momento no puedo procesar tu consulta. Por favor, intentá de nuevo más tarde o comunicate con el área correspondiente.';

function falla(motivo) {
  const f = prep.fila;
  return [{ json: { insertar: false, final: {
    id_consulta: f.id_consulta, origen: f.origen, legajo: f.legajo, fecha_hora: f.fecha_hora,
    decision: '', procedimiento: 'SIN_CLASIFICAR', categoria: 'SIN_CLASIFICAR', area_destino: '', urgencia: 'Normal',
    respuesta: RESPUESTA_ERROR, resumen: '[no disponible]', fuentes: '', id_solicitud: '',
    estado_procesamiento: 'ERROR', codigo_error: 'ERR_SHEETS', registro: 'NO_REGISTRADA',
    control: { motivo, resultado_original: prep.salida.estado_procesamiento },
  } } }];
}

if (!prep.puede_registrar) return falla('DATOS_DE_CONTROL_INVALIDOS');
if (items.some(r => r.error)) return falla('ERROR_BUSQUEDA_DUPLICADOS');

const existentes = items.filter(r => String(r.id_consulta ?? '').trim() === prep.fila.id_consulta);
if (existentes.length > 0) {
  return [{ json: { insertar: false, final: { ...prep.salida, registro: 'YA_REGISTRADA' } } }];
}
return [{ json: { insertar: true } }];

// Confirmar registro: solo se informa REGISTRADA si la escritura respondió sin error.
const prep = $('Preparar registro').first().json;
const r = $input.first().json || {};
const RESPUESTA_ERROR = 'En este momento no puedo procesar tu consulta. Por favor, intentá de nuevo más tarde o comunicate con el área correspondiente.';
const escrita = !r.error && String(r.id_consulta ?? '').trim() === prep.fila.id_consulta;

if (!escrita) {
  const f = prep.fila;
  return [{ json: { final: {
    id_consulta: f.id_consulta, origen: f.origen, legajo: f.legajo, fecha_hora: f.fecha_hora,
    decision: '', procedimiento: 'SIN_CLASIFICAR', categoria: 'SIN_CLASIFICAR', area_destino: '', urgencia: 'Normal',
    respuesta: RESPUESTA_ERROR, resumen: '[no disponible]', fuentes: '', id_solicitud: '',
    estado_procesamiento: 'ERROR', codigo_error: 'ERR_SHEETS', registro: 'NO_REGISTRADA',
    control: { motivo: 'ERROR_ESCRITURA_CONSULTAS', resultado_original: prep.salida.estado_procesamiento },
  } } }];
}
return [{ json: { final: { ...prep.salida, registro: 'REGISTRADA' } } }];

// Configuración del aviso de derivación.
// Solo se envía a una casilla de pruebas de la lista autorizada por el responsable del proyecto.
// Nunca usar direcciones @cordal.example. Valores vacíos en la versión de entrega: configurar la casilla autorizada antes de habilitar el envío.
const AVISO_DESTINATARIOS_AUTORIZADOS = [];
const AVISO_DESTINATARIO = '';
const AVISO_ENVIO_HABILITADO = false;
return [{ json: { ...$input.first().json, aviso_destinatario: AVISO_DESTINATARIO, aviso_destinatarios_autorizados: AVISO_DESTINATARIOS_AUTORIZADOS, aviso_envio_habilitado: AVISO_ENVIO_HABILITADO } }];

// Preparar aviso: decide con lógica fija si corresponde avisar una derivación y arma el correo.
// No envía nada. El contenido sale de la fila ya registrada en Consultas, nunca del mensaje original.
const entrada = $input.first().json;
const final = entrada.final || {};
const destinatario = String(entrada.aviso_destinatario ?? '').trim();
const envioHabilitado = entrada.aviso_envio_habilitado === true;
const autorizados = Array.isArray(entrada.aviso_destinatarios_autorizados) ? entrada.aviso_destinatarios_autorizados.map(d => String(d).trim().toLowerCase()) : [];
let fila = {};
try { fila = $('Preparar registro').first().json.fila || {}; } catch (e) { fila = {}; }

const AREAS = ['Recursos Humanos', 'Salud Ocupacional', 'Administración y Finanzas', 'Mesa de Ayuda IT', 'Seguridad Informática', 'Pañol y Logística'];
const salida = (aviso, enviar, correo) => [{ json: { final, aviso, enviar, correo: correo || null } }];

// 1) Condiciones de negocio y de registro (en este orden)
let motivo = '';
if (final.decision !== 'DERIVAR') motivo = 'DECISION_NO_DERIVAR';
else if (final.estado_procesamiento !== 'COMPLETADO') motivo = 'ESTADO_NO_COMPLETADO';
else if (final.registro === 'YA_REGISTRADA') motivo = 'REGISTRO_YA_EXISTENTE';
else if (final.registro !== 'REGISTRADA') motivo = 'REGISTRO_FALLIDO';
else if (!AREAS.includes(final.area_destino) || fila.area_destino !== final.area_destino) motivo = 'AREA_NO_PERMITIDA';
else if (fila.id_consulta !== final.id_consulta || fila.estado_derivacion !== 'Pendiente' || fila.estado_aviso !== 'PENDIENTE') motivo = 'REGISTRO_INCONSISTENTE';
// estado_aviso informa lo escrito en Consultas en esta ejecución; vacío si esta ejecución no registró la fila.
const estadoAvisoRegistrado = final.registro === 'REGISTRADA' ? (fila.estado_aviso || '') : '';
if (motivo) return salida({ estado: 'NO_CORRESPONDE', motivo, estado_aviso: estadoAvisoRegistrado }, false);

// 2) Correo con información mínima, tomada de la fila registrada
const asunto = '[PRUEBA ACADÉMICA] ' + (fila.urgencia === 'Alta' ? '[URGENTE] ' : '') + 'Derivación pendiente ' + fila.id_consulta + ' - ' + fila.area_destino;
const cuerpo = [
  'Derivación pendiente de atención (prototipo académico, datos ficticios).',
  '',
  'Consulta: ' + fila.id_consulta,
  'Legajo: ' + fila.legajo,
  'Procedimiento: ' + fila.procedimiento,
  'Área de destino: ' + fila.area_destino,
  'Urgencia: ' + fila.urgencia,
  'Resumen: ' + (fila.resumen || '[no disponible]'),
  'Fuentes: ' + (fila.fuentes || 'sin fuentes citadas'),
  'Estado de la derivación: Pendiente',
  '',
  'Este aviso no indica que el caso haya sido tomado ni resuelto. El seguimiento se registra en la pestaña Consultas.',
  'El mensaje original del empleado no se incluye en este aviso.',
].join('\n');

// 3) Control de contenido antes de enviar: sin mensaje original, sin direcciones de correo ni datos sensibles
let mensajeOriginal = '';
try { mensajeOriginal = String($('Recibir consulta').first().json.mensaje || '').trim(); } catch (e) { mensajeOriginal = ''; }
const textoCorreo = asunto + '\n' + cuerpo;
const sinLegajo = mensajeOriginal.replace(/^LEG-\d{4}[\s:,.-]*/i, '').trim();
const incluyeOriginal = sinLegajo.length >= 20 && textoCorreo.includes(sinLegajo.slice(0, 40));
const datoSensible = /@|contrase[ñn]a|password|token|diagn[oó]stic|certificado m[eé]dic|enfermedad|\bcbu\b|tarjeta de cr[eé]dito|\bdni\b|\d{6,}|\$\s?\d/i.test(textoCorreo);
if (incluyeOriginal || datoSensible) {
  return salida({ estado: 'NO_ENVIADO', motivo: 'CONTENIDO_NO_PERMITIDO', estado_aviso: 'PENDIENTE' }, false, { asunto, cuerpo });
}

// 4) Destinatario: solo una casilla de pruebas autorizada de la lista; nunca @cordal.example
const formatoValido = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(destinatario);
if (!destinatario || !formatoValido || /@cordal\.example$/i.test(destinatario) || !autorizados.includes(destinatario.toLowerCase())) {
  return salida({ estado: 'NO_ENVIADO', motivo: 'SIN_DESTINATARIO_AUTORIZADO', estado_aviso: 'PENDIENTE' }, false, { asunto, cuerpo });
}
if (!envioHabilitado) return salida({ estado: 'NO_ENVIADO', motivo: 'ENVIO_DESHABILITADO', estado_aviso: 'PENDIENTE' }, false, { asunto, cuerpo });

return salida({ estado: 'PENDIENTE_DE_ENVIO', motivo: '', estado_aviso: 'PENDIENTE' }, true, { para: destinatario, asunto, cuerpo });

// Resultado del aviso: interpreta la respuesta del nodo Gmail, sin reintentar.
// ENVIADO = Gmail aceptó el mensaje y devolvió su identificador. No significa entregado, leído ni atendido.
// ERROR = Gmail rechazó el pedido con un error confirmado (pedido inválido, credencial, permisos o cuota).
// Cualquier otro caso (tiempo de espera, corte de conexión, error del servidor, respuesta sin identificador)
// es incierto: no se asume que no se envió. Queda PENDIENTE y se marca para verificación manual.
const prep = $('Preparar aviso').first().json;
const r = $input.first().json || {};
const idMensaje = (!r.error && typeof r.id === 'string' && r.id) ? r.id : '';
const textoError = r.error ? JSON.stringify(r.error) + ' ' + JSON.stringify(r.description ?? '') : '';
const rechazoConfirmado = /\b(400|401|403|404|429)\b|bad request|invalid to header|invalid recipient|unauthorized|forbidden|invalid_grant|insufficient permission|rate limit|quota/i.test(textoError);
const incierto = /timeout|timed out|ETIMEDOUT|ECONNRESET|ECONNABORTED|socket hang up|\b5\d\d\b/i.test(textoError);
let aviso, actualizar;
if (idMensaje) {
  aviso = { estado: 'ENVIADO', motivo: '', id_mensaje: idMensaje, estado_aviso: 'ENVIADO' };
  actualizar = true;
} else if (r.error && rechazoConfirmado && !incierto) {
  aviso = { estado: 'ERROR_ENVIO', motivo: 'ERROR_GMAIL', estado_aviso: 'ERROR' };
  actualizar = true;
} else {
  aviso = { estado: 'VERIFICACION_MANUAL', motivo: r.error ? 'RESULTADO_INCIERTO_GMAIL' : 'SIN_CONFIRMACION_DE_GMAIL', estado_aviso: 'PENDIENTE', verificacion_manual: true };
  actualizar = false;
}
return [{ json: { final: prep.final, aviso, actualizar } }];

// Respuesta final para WF-02: resultado del procesamiento, del registro y del aviso, por separado.
const d = $input.first().json;
return [{ json: { ...d.final, aviso: d.aviso } }];

// Confirmar estado del aviso: verifica que Consultas haya guardado ENVIADO o ERROR para esta consulta.
// Si Gmail aceptó el mensaje pero la planilla no se actualizó, la fila sigue en PENDIENTE:
// el caso requiere verificación manual y no es seguro reenviar.
const res = $('Resultado del aviso').first().json;
const u = $input.first().json || {};
const ok = !u.error && u.id_consulta === res.final.id_consulta && u.estado_aviso === res.aviso.estado_aviso;
const aviso = ok
  ? { ...res.aviso, estado_aviso_registrado: true }
  // estado_aviso queda vacío: no se pudo confirmar qué valor tiene la planilla (lo esperable es PENDIENTE).
  : { ...res.aviso, estado_aviso: '', estado_aviso_registrado: false, verificacion_manual: true,
      motivo: res.aviso.estado === 'ENVIADO' ? 'ENVIADO_SIN_ACTUALIZAR_ESTADO' : 'ERROR_SIN_ACTUALIZAR_ESTADO' };
return [{ json: { final: res.final, aviso } }];
